codeFiles.source:
#include <stdio.h>

int main(void) {
    FILE *fp = fopen("diary.txt", "w");

    if (fp == NULL) {
        printf("Could not open diary.txt\n");
        return 1;
    }

    fprintf(fp, "Day 1: Learned files in C\n");
    fprintf(fp, "Fish caught: %d\n", 7);
    fputs("Mood: happy\n", fp);

    fclose(fp);
    printf("Saved to diary.txt\n");
    return 0;
}

